import{_ as e,o as t,c as r,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const l=JSON.parse('{"title":"How Rook/Ceph Enables Science @ Rubin Observatory - Joshua Hoblitt, Rubin Observatory","description":"","frontmatter":{"title":"How Rook/Ceph Enables Science @ Rubin Observatory - Joshua Hoblitt, Rubin Observatory","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-19T00:00:00.000Z","tags":["Ceph","Rook","Kubernetes","Distributed Storage","Astronomy"],"categories":["会议纪要","技术文章"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/How_Rook_Ceph_Enables_Science_@_Rubin_Observatory_-_Joshua_Hoblitt_Rubin_Observatory.md","filePath":"posts/2025/How_Rook_Ceph_Enables_Science_@_Rubin_Observatory_-_Joshua_Hoblitt_Rubin_Observatory.md","lastUpdated":1780459816000}'),n={name:"posts/2025/How_Rook_Ceph_Enables_Science_@_Rubin_Observatory_-_Joshua_Hoblitt_Rubin_Observatory.md"};function a(p,o,_,i,b,R){return t(),r("div",null,[...o[0]||(o[0]=[s("<p>Rubin Observatory 的首席 DevOps 工程师 Joshua Hoblitt 在其演讲中详细介绍了 Rubin Observatory 如何利用 Ceph 和 Rook 技术实现其存储架构的统一，以支持天文数据的高吞吐和高可用需求。</p><p><strong>Rubin Observatory 背景</strong></p><p>Rubin Observatory 是一个由 NSF/DOE 联合资助的项目，位于智利 Cerro Pachón 山上。其科学目标包括研究暗物质、太阳系测绘、银河系映射等。每晚观测会产生约 20TB 的原始数据，并包含数百万次瞬变事件警报。</p><p><strong>数据流架构</strong></p><p>Rubin Observatory 的数据流包括从 LSST Camera 捕获数据，经过数据采集系统（DAC）处理，再通过诊断集群节点转换为 FITS 格式并压缩。数据主要通过 RGW 写入 USDF，同时也复制到本地的 RGW 实例，并通过 Kafka 通知导入 OODS。</p><p><strong>选择 Ceph 和 Rook 的原因</strong></p><p>Rubin Observatory 选择 Ceph 和 Rook 的原因包括：</p><ul><li><strong>统一存储</strong>：Ceph 支持 RBD、CephFS 和 RGW，提供了一种统一的存储解决方案。</li><li><strong>高可用性</strong>：Ceph 通过 CRUSH 算法和 PG 实现分布式冗余，确保数据的高可用性。</li><li><strong>扩展性</strong>：Ceph 可轻松扩展至千级 OSD，满足 Rubin Observatory 的存储需求。</li><li><strong>Kubernetes 集成</strong>：Rook 提供了 Kubernetes 原生集成，简化了部署和管理过程。</li><li><strong>GitOps 支持</strong>：Rook 与 GitOps 实践相结合，实现配置版本化和自动化。</li></ul><p><strong>当前存储集群状态</strong></p><p>Rubin Observatory 的存储集群已启用 OSD 加密，并计划部署 1,100+ OSD。集群使用了 RBD、RGW 和 CephFS，同时通过 NFS-Ganesha 提供文件共享功能。</p><p><strong>挑战与优化</strong></p><p>Rubin Observatory 面临的主要挑战包括性能敏感型负载和 NFS 性能。对于性能敏感型负载，如 InfluxDB 和 Kafka，目前仍使用本地 NVMe 存储。NFS 性能问题可能与使用的 NFS-Ganesha 版本有关。</p><p><strong>GitOps 工作流</strong></p><p>Rubin Observatory 使用 GitOps 模型进行存储管理。所有 Rook 资源都存储在公共 Git 仓库中，通过 PR 提交到 <code>dev</code> 分支，并自动同步到生产环境。</p><p><strong>后续行动计划</strong></p><p>Rubin Observatory 计划继续优化性能，测试新的 NFS-Ganesha 版本，并评估使用 CephFS 直挂替代 NFS 的可能性。此外，Rubin Observatory 还计划扩展其存储集群，并考虑组织 Rook 研讨会，帮助团队更好地使用 Kubernetes。</p><p><strong>关键词保留</strong>：Ceph, Rook, OSD, CRUSH, RGW, CephFS, RBD, EC, GitOps, Kubernetes</p>",17)])])}const O=e(n,[["render",a]]);export{l as __pageData,O as default};
